#[derive(Copy, Clone, PartialEq, Eq, Debug)]
pub enum LineEnding { Lf, CrLf, Cr }
impl LineEnding { pub fn as_str(self) -> &'static str; }

/// Alias so callers never spell the encoding_rs path.
pub type Encoding = &'static encoding_rs::Encoding;

#[derive(Clone, Debug)]
pub struct DecodeOptions {
    pub fallback: Encoding,          // used when bytes are not valid UTF-8 and carry no BOM
    pub max_bytes: u64,              // refuse larger files loudly instead of swapping to death
}
impl Default for DecodeOptions { /* fallback = WINDOWS_1252, max_bytes = 2 GiB */ }

#[derive(Clone, Debug, PartialEq)]
pub struct Decoded {
    pub text: ropey::Rope,           // line endings normalized to \n
    pub encoding: Encoding,
    pub bom: bool,
    pub line_ending: LineEnding,     // majority ending seen; Lf when none
    pub had_malformed: bool,         // replacement chars were inserted
    pub probably_binary: bool,       // NUL byte in the first 8 KiB
}

pub fn decode(bytes: &[u8], opts: &DecodeOptions) -> Result<Decoded, DecodeError>;

#[derive(Debug)]
pub enum DecodeError { TooLarge { size: u64, limit: u64 } }

#[derive(Debug)]
pub struct Loaded {
    pub decoded: Decoded,
    pub size_bytes: u64,
    pub mtime: Option<std::time::SystemTime>,
    pub digest: [u8; 32],            // SHA-256 of the bytes on disk, for modified-on-disk checks
}

pub fn load(path: &std::path::Path, opts: &DecodeOptions) -> Result<Loaded, LoadError>;

#[derive(Debug)]
pub enum LoadError { Io(std::io::Error), Decode(DecodeError) }
